import * as THREE from "three";

export type OverlayFlavor = "creeper" | "wither" | "slime" | "glint";

export const OVERLAY_ID_FLAVORS: Record<string, OverlayFlavor> = {
  "7294a49d-ff58-495b-a5e4-573260e2a109": "creeper",
  "9559926c-96f9-4f8e-8fc8-2a6d16bdc4df": "wither",
  "5c5855ce-a461-4734-b365-5a35871733c3": "slime",
};

export function overlayFlavorFor(
  id: string | null | undefined,
  path: string
): OverlayFlavor {
  if (id && OVERLAY_ID_FLAVORS[id]) return OVERLAY_ID_FLAVORS[id];
  const p = path.toLowerCase();
  if (p.includes("wither")) return "wither";
  if (p.includes("creeper")) return "creeper";
  if (p.includes("slime")) return "slime";
  return "glint";
}

export interface OverlayStyle {
  filter: THREE.MagnificationTextureFilter;
  matrixAutoUpdate: boolean;
  applyBlend(material: THREE.MeshBasicMaterial): void;
  animate(texture: THREE.Texture, elapsedSeconds: number): void;
  resolveAlpha(alpha: number): number;
}

function additiveBlend(m: THREE.MeshBasicMaterial): void {
  m.blending = THREE.AdditiveBlending;
}

function glintBlend(m: THREE.MeshBasicMaterial): void {
  m.blending = THREE.CustomBlending;
  m.blendEquation = THREE.AddEquation;
  m.blendSrc = THREE.SrcColorFactor;
  m.blendDst = THREE.OneFactor;
  m.blendSrcAlpha = THREE.ZeroFactor;
  m.blendDstAlpha = THREE.OneFactor;
}

const identity = (a: number) => a;

export const OVERLAY_STYLES: Record<OverlayFlavor, OverlayStyle> = {
  creeper: {
    filter: THREE.NearestFilter,
    matrixAutoUpdate: true,
    applyBlend: additiveBlend,
    animate: (texture, t) => {
      const age = t * 20;
      texture.offset.set((age * 0.01) % 1, (age * 0.01) % 1);
    },
    resolveAlpha: identity,
  },
  wither: {
    filter: THREE.NearestFilter,
    matrixAutoUpdate: true,
    applyBlend: additiveBlend,
    animate: (texture, t) => {
      const age = t * 20;
      texture.offset.set((Math.cos(age * 0.02) * 3) % 1, (age * 0.01) % 1);
    },
    resolveAlpha: identity,
  },
  slime: {
    filter: THREE.NearestFilter,
    matrixAutoUpdate: true,
    applyBlend: (m) => {
      m.blending = THREE.NormalBlending;
    },
    animate: () => {},
    resolveAlpha: (a) => Math.max(0.01, Math.min(0.7, a)),
  },
  glint: {
    filter: THREE.LinearFilter,
    matrixAutoUpdate: false,
    applyBlend: glintBlend,
    animate: (texture, t) => {
      const time = t * 4000;
      const tx = (time % 110000) / 110000;
      const ty = (time % 30000) / 30000;
      const k = 0.5;
      const a = Math.PI / 18;
      const c = Math.cos(a) * k;
      const s = Math.sin(a) * k;
      texture.matrix.set(c, -s, tx, s, c, ty, 0, 0, 1);
    },
    resolveAlpha: identity,
  },
};
